          <button type="submit" disabled={loading} style={{ ...S.btnPrimary, padding: "12px", marginTop: "8px", fontSize: "14px" }}>
            {loading ? "Signing in…" : "Sign in →"}
          </button>
        </form>
      </div>
    </div>
  );
}

