                  <p className="sol-split-desc">{sol.intro}</p>
                  {sol.features && sol.features.length > 0 && (
                    <div className="svc-split-tags">
                      {sol.features.slice(0, 6).map((s) => (
                        <span key={s} className="svc-split-tag">{s}</span>
                      ))}
                    </div>
                  )}
                  <Link to={`/solutions/${sol.slug}`} className="svc-split-cta">
                    Explore solution →
                  </Link>
                </div>
              </div>

              {/* Image half */}
              <div className="sol-split-img relative min-h-[300px] overflow-hidden">
                {img && <Image src={img} alt={sol.title} fill sizes="(max-width: 768px) 100vw, 50vw" className="object-cover" />}
              </div>
            </article>
          );
        })}
      </section>
      <FinalCTA />
    </>
  );
}

export function SolutionDetail({ solution }) {
  if (!solution) return <NotFound />;
  const img = solution.image_url;
  return (
    <>
      <PageHero
        eyebrow={`Solution`}
        title={solution.title}
        copy={solution.ideal_for}
        image={img}
        imageAlt="Solution visual"
      />
      <section className="section sol-detail-body">
        <div className="svc-two-col">
          <div>
            <p className="eyebrow">What this solution covers</p>
            <p style={{ fontSize: 17, lineHeight: 1.7, color: "var(--text-muted)", marginBottom: 20 }}>
              {solution.intro}
            </p>
          </div>
          <div>
            <p className="eyebrow">Engagement steps</p>
            <ul className="svc-deliverables-list">
              {(solution.features || []).map((s, i) => (
                <li key={s}><span>{String(i + 1).padStart(2, "0")}</span>{s}</li>
              ))}
            </ul>
          </div>
        </div>
      </section>
      <FinalCTA serviceSlug={solution.slug} />
    </>
  );
}

"use client";
/** pages/Team.jsx */
import Image from "next/image";
import { PageHero } from "@/components/shared/PageHero";
import { LoadingSpinner } from "@/components/shared/LoadingSpinner";
const productDesign = "/assets/vyoma-product-design.webp";
import { AnimatedTooltip } from "@/components/ui/animated-tooltip";
import { FinalCTA } from "@/components/shared/FinalCTA";

const GROUPS = ["Leadership", "Design", "Engineering", "AI & ML", "Quality & Delivery"];

export function Team({ initialMembers = [] }) {
  const team = initialMembers;

  return (
    <>
      <PageHero
        eyebrow="Team"
        title="Different expertise. One team."
        copy="VYOMA is designed to bring product, design, engineering, and intelligence into one connected delivery model."
        image={productDesign}
        imageAlt="Product system visual"
      />

      <div className="flex flex-row items-center justify-center my-10 w-full">
        {team && (
          <AnimatedTooltip
            items={team.map((m) => ({
              id: m.id,
              name: m.name,
              designation: m.role,
              image: m.image_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(m.name)}`,
            }))}
          />
        )}
      </div>

      {GROUPS.map(group => {
          const members = team.filter(m => (m.group || "Leadership") === group);
          if (!members.length) return null;
          return (
            <section key={group} className="section team-group">
              <p className="eyebrow team-group-label">{group}</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
                {members.map(member => (
                  <article key={member.id} className="flex flex-col md:flex-row gap-6 p-6 md:p-8 rounded-2xl bg-[var(--surface)] border border-[var(--border)] hover:border-[var(--border-strong)] transition-colors shadow-sm">
                    <div className="relative w-20 h-20 md:w-32 md:h-32 rounded-full overflow-hidden flex-shrink-0 border border-[var(--accent)]/30 drop-shadow-md">
                      <Image
                        src={member.image_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(member.name)}&background=random`}
                        alt={`${member.name} — ${member.role} at VYOMA`}
                        fill
                        sizes="128px"
                        className="object-cover"
                      />
                    </div>
                    <div className="flex flex-col justify-start flex-grow">
                      <h3 className="text-xl md:text-2xl font-display font-bold text-[var(--text)] mb-1">{member.name}</h3>
                      <span className="text-sm font-mono text-[var(--text-dim)] block mb-1">{member.role}</span>
                      <span className="text-xs font-mono text-[var(--accent)] block mb-4">{member.specialization}</span>
                      
                      <p className="text-sm text-[var(--text-muted)] leading-relaxed mb-6 flex-grow">
                        {member.bio || "Passionate about building scalable digital products and driving technological innovation forward."}
                      </p>
                      
                      <div className="mt-auto pt-4 border-t border-[var(--border)]">
                        <a 
                          href={`mailto:${member.email || member.name.split(' ')[0].toLowerCase() + '@vyomatechnologies.com'}`} 
                          className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[var(--bg)] bg-[var(--text)] px-4 py-2 rounded-md hover:bg-[var(--accent)] hover:text-white transition-all shadow-sm"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <rect width="20" height="16" x="2" y="4" rx="2"/>
                            <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"/>
                          </svg>
                          Contact via Email
                        </a>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </section>
          );
        })}

      <FinalCTA />
    </>
  );
}

"use client";
/** pages/Work.jsx */
import { useState } from "react";
import { PageHero } from "@/components/shared/PageHero";
import { ProjectCard } from "@/components/shared/ProjectCard";
import { LoadingSpinner } from "@/components/shared/LoadingSpinner";

const FILTERS = ["ALL", "WEB", "MOBILE", "AI", "SAAS", "SOFTWARE", "DESIGN"];

export function Work({ initialProjects = [] }) {
  const [filter, setFilter] = useState("ALL");
  const projects = initialProjects;

  const filtered = filter === "ALL"
    ? projects
    : projects.filter(p => p.role?.toUpperCase().includes(filter) || p.tags?.some(t => t.toUpperCase().includes(filter)));

  return (
    <>
      <PageHero
        eyebrow="Selected Work"
        title="The work is the proof."
        copy="A growing archive of product thinking, interface decisions, system design, and applied AI — built for real problems, designed for real users."
      />
      <section className="section work-index">
        <div className="work-filter-bar">
          {FILTERS.map(c => (
            <button
              key={c}
              className={`filter-btn${filter === c ? " active" : ""}`}
              onClick={() => setFilter(c)}
            >
              {c}
            </button>
          ))}
        </div>
        {filtered.length === 0 ? (
          <p style={{ color: "var(--text-muted)", textAlign: "center", padding: "80px 0" }}>No projects found.</p>
        ) : (
          <div className="project-grid-full">
            {filtered.map(p => <ProjectCard key={p.slug} project={p} />)}
          </div>
        )}
      </section>
    </>
  );
}
